import type {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

const validators: Record<string, (message: Record<string, unknown>) => ValidationResult> = {
  user_message: validateUserMessage,
  ping: validatePingMessage,
  list_sessions: validateListSessionsMessage,
};

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validator = validators[message.type];
  if (validator) {
    return validator(message);
  }

  return {valid: false, error: `Unknown message type: ${message.type}`};
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const result: ListSessionsMessage = {type: 'list_sessions'};

  const limitResult = validateLimit(message.limit);
  if (!limitResult.valid) return limitResult;
  if (limitResult.data !== undefined) result.limit = limitResult.data;

  const beforeResult = validateBefore(message.before);
  if (!beforeResult.valid) return beforeResult;
  if (beforeResult.data !== undefined) result.before = beforeResult.data;

  return {
    valid: true,
    data: result,
  };
}

function validateLimit(limit: unknown): {valid: true; data?: number} | ValidationFailure {
  if (limit === undefined) return {valid: true};
  if (typeof limit !== 'number' || !Number.isInteger(limit) || limit < 0) {
    return {valid: false, error: 'limit must be a non-negative integer'};
  }
  return {valid: true, data: limit};
}

function validateBefore(
  before: unknown
): {valid: true; data?: {sessionId: string; updatedAt: string | number}} | ValidationFailure {
  if (before === undefined) return {valid: true};
  if (typeof before !== 'object' || before === null) {
    return {valid: false, error: 'before must be an object'};
  }

  const beforeObj = before as Record<string, unknown>;

  if (typeof beforeObj.sessionId !== 'string' || beforeObj.sessionId.length < 1 || beforeObj.sessionId.length > 128) {
    return {valid: false, error: 'before.sessionId must be a string of 1-128 characters'};
  }

  if (typeof beforeObj.updatedAt !== 'string' && typeof beforeObj.updatedAt !== 'number') {
    return {valid: false, error: 'before.updatedAt must be a string or number'};
  }

  const date = new Date(beforeObj.updatedAt);
  if (!Number.isFinite(date.getTime())) {
    return {valid: false, error: 'before.updatedAt must be a finite date'};
  }

  return {
    valid: true,
    data: {
      sessionId: beforeObj.sessionId,
      updatedAt: beforeObj.updatedAt,
    },
  };
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

import {WebSocket} from 'ws';
import type {SessionEntry} from '../../types/session.js';
import type {ChatSession} from '../../types/session.js';
import {ErrorCodes} from '../../types/messages.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
import {validateMessage} from './validation.js';
import type {ValidationResult} from './validation.js';
import {PerSessionLock} from '../../shared/perSessionLock.js';
import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import {AIError} from '../../types/ai.js';
import type {MessageChunk} from '../../types/ai.js';
import {
  createUserEntry,
  createAssistantEntry,
  createThinkingEntry,
  createToolEntry,
} from '../../orchestration/entryFactories.js';
import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
import {sendJson, sendUpsert, sendDelta, sendCommit, sendSkip, sendError, sendStreamEnd} from './sender.js';
import {log} from '../../shared/logger.js';

interface StreamState {
  thinkingIndex: number | null;
  assistantIndex: number | null;
  suppressOutput: boolean;
  sentAssistantIndices: number[];
}

type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
export function createMessageHandler(orchestrator: ChatOrchestrator) {
  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
  const lock = new PerSessionLock();
  return function handleMessage(
    ws: WebSocket,
    session: ChatSession,
    rawMessage: unknown,
    signal?: AbortSignal
  ): Promise<void> {
    const validation = validateMessage(rawMessage);
    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
    if (isUserMessageFrame(rawMessage)) {
      return lock.run(session.sessionId, () => answerInTurn(ws, session, orchestrator, validation, signal));
    }
    // An async action runs up to its first await at once, so a ping is answered now and a throw stays a rejection.
    return wsErrorHandler(ws, async () => answerFrame(ws, validation));
  };
}

// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
async function answerInTurn(
  ws: WebSocket,
  session: ChatSession,
  orchestrator: ChatOrchestrator,
  validation: ValidationResult,
  signal: AbortSignal | undefined
): Promise<void> {
  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
    return;
  }
  const startedAt = Date.now();
  try {
    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, signal));
  } finally {
    endTurn(ws, session, signal, startedAt);
  }
}

// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
  if (signal?.aborted) {
    log.info('message', 'turn abandoned: its socket closed', {
      sessionId: session.sessionId,
      elapsedMs: Date.now() - startedAt,
    });
    return;
  }
  sendStreamEnd(ws);
}

async function answerUserMessage(
  ws: WebSocket,
  session: ChatSession,
  orchestrator: ChatOrchestrator,
  validation: ValidationResult,
  signal: AbortSignal | undefined
): Promise<void> {
  const message = validation.valid ? validation.data : undefined;
  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
  answerFrame(ws, validation);
}

function answerFrame(ws: WebSocket, validation: ValidationResult): void {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
}

// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
function isUserMessageFrame(rawMessage: unknown): boolean {
  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
}

async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
  try {
    await action();
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unknown error';
    const code = error instanceof AIError ? error.code : 'UNKNOWN';
    log.error('message', 'handling error', {error: message, code});
    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
      return;
    }
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
  }
}

async function handleUserMessage(
  ws: WebSocket,
  session: ChatSession,
  orchestrator: ChatOrchestrator,
  content: string,
  signal: AbortSignal | undefined
): Promise<void> {
  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});

  const userEntry = createUserEntry(content);
  const userIndex = appendEntry(session, userEntry);
  sendUpsert(ws, userIndex, userEntry);

  const parser = new ThinkingTagParser();
  const state: StreamState = {
    thinkingIndex: null,
    assistantIndex: null,
    suppressOutput: false,
    sentAssistantIndices: [],
  };

  let textChunkCount = 0;

  try {
    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
      if (signal?.aborted) break;
      textChunkCount = logChunk(chunk, textChunkCount);
      processChunk(ws, session, state, parser, chunk);
    }
  } finally {
    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
    flushHeldText(ws, session, state, parser);
    closeCutOff(ws, session, state, 'thinkingIndex');
    closeCutOff(ws, session, state, 'assistantIndex');
  }

  if (textChunkCount > 0) {
    log.debug('stream', `received ${textChunkCount} text chunks`);
  }
  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
}

// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
function logChunk(chunk: MessageChunk, textChunkCount: number): number {
  if (chunk.type === 'text') return textChunkCount + 1;

  if (textChunkCount > 0) {
    log.debug('stream', `received ${textChunkCount} text chunks`);
  }

  if (chunk.type === 'tool_result') {
    log.debug('stream', 'tool_result chunk', {
      messageCount: chunk.clientMessages.length,
      types: chunk.clientMessages.map(m => m.type),
    });
    return 0;
  }

  log.debug('stream', 'chunk', {type: chunk.type});
  return 0;
}

function processChunk(
  ws: WebSocket,
  session: ChatSession,
  state: StreamState,
  parser: ThinkingTagParser,
  chunk: MessageChunk
): void {
  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
}

function processTextChunk(
  ws: WebSocket,
  session: ChatSession,
  state: StreamState,
  parser: ThinkingTagParser,
  text: string
): void {
  const segments = parser.push(text);
  for (const segment of segments) {
    handleTextSegment(ws, session, state, segment);
  }
}

function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
  if (segment.type === 'thinking') {
    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
    return;
  }
  commitAndClear(ws, session, state, 'thinkingIndex');
  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
}

function streamSegment(
  ws: WebSocket,
  session: ChatSession,
  state: StreamState,
  key: StateIndexKey,
  createEntry: EntryFactory,
  content: string
): void {
  const isNew = initSegment(session, state, key, createEntry);
  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
  appendDelta(session, state[key]!, content);
  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
}

// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
  markSuppressed(session, index);
  sendSkip(ws, index);
}

function markSuppressed(session: ChatSession, index: number): void {
  const entry = session.entries[index];
  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
}

function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
  if (state[key] !== null) return false;
  state[key] = appendEntry(session, createEntry());
  return true;
}

function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
  const index = state[key];
  if (index === null) return;

  commitEntry(session, index);
  state[key] = null;

  // Only what the client received can be retracted, and only assistant entries.
  if (state.suppressOutput) return;

  sendCommit(ws, index);
  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
}

function processToolUseChunk(
  ws: WebSocket,
  session: ChatSession,
  toolCall: {name: string; input: Record<string, unknown>}
): void {
  const toolEntry = createToolEntry(toolCall.name, toolCall.input);
  const toolIndex = appendEntry(session, toolEntry);
  sendUpsert(ws, toolIndex, toolEntry);
}

function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
  for (const msg of clientMessages) {
    log.debug('stream', 'forwarding client message to frontend', {
      type: msg.type,
      index: 'index' in msg ? msg.index : undefined,
    });
    sendJson(ws, msg);
  }
}

// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
  commitOpenEntries(ws, session, state);
  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});

  for (const idx of state.sentAssistantIndices) {
    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
    markSuppressed(session, idx);
  }

  state.sentAssistantIndices = [];
  state.suppressOutput = true;
}

function processStopChunk(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
  flushHeldText(ws, session, state, parser);
  commitOpenEntries(ws, session, state);
}

// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
  for (const segment of parser.flush()) {
    handleTextSegment(ws, session, state, segment);
  }
}

// The flag lives on the stored entry even when suppressed; only a visible entry is re-sent, which is how a live client learns it.
function closeCutOff(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
  const index = state[key];
  if (index === null) return;
  markTruncated(session, index);
  if (!state.suppressOutput) sendUpsert(ws, index, session.entries[index]);
  commitAndClear(ws, session, state, key);
}

function commitOpenEntries(ws: WebSocket, session: ChatSession, state: StreamState): void {
  commitAndClear(ws, session, state, 'thinkingIndex');
  commitAndClear(ws, session, state, 'assistantIndex');
}

function handlePing(ws: WebSocket, timestamp: number): void {
  ws.send(JSON.stringify({type: 'pong', timestamp}));
}

import http from 'http';
import {WebSocketServer} from 'ws';
import type {Express} from 'express';
import type {WsAuthenticator} from '../types/auth.js';
import type {SessionStore} from '../types/sessionStore.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
import type {ToolRegistry} from '../orchestration/tools/registry.js';
import {createUpgradeHandler, createConnectionHandler, ExtWebSocket} from './ws/connectionHandler.js';
import {createMessageHandler} from './ws/messageHandler.js';
import {selectSubprotocol} from './ws/subprotocol.js';
import type {ConnectInfo, SessionResumeOptions} from './ws/sessionResume.js';
import {log} from '../shared/logger.js';

export interface HalServerOptions {
  app: Express;
  wsAuth: WsAuthenticator;
  sessionStore: SessionStore;
  orchestrator: ChatOrchestrator;
  toolRegistry?: ToolRegistry;
  basePath?: string;
  port?: number;
  heartbeatIntervalMs?: number;
  onConnect?: (session: import('../types/session.js').ChatSession, connection: ConnectInfo) => void | Promise<void>;
  onDisconnect?: (sessionId: string) => void | Promise<void>;
  resume?: SessionResumeOptions;
}

export interface HalServer {
  server: http.Server;
  wss: WebSocketServer;
  start: (port?: number) => Promise<void>;
  stop: () => Promise<void>;
}

export function createServer(options: HalServerOptions): HalServer {
  const basePath = options.basePath ?? '/hal';

  const wss = new WebSocketServer({
    noServer: true,
    handleProtocols: selectSubprotocol,
  });

  const handleMessage = createMessageHandler(options.orchestrator);
  const examplePrompts = options.toolRegistry?.getExamplePrompts() ?? [];

  const deps = {
    wsAuth: options.wsAuth,
    sessionStore: options.sessionStore,
    handleMessage,
    basePath,
    onConnect: options.onConnect,
    onDisconnect: options.onDisconnect,
    resume: options.resume,
  };

  const handleUpgrade = createUpgradeHandler(wss, deps);
  const handleConnection = createConnectionHandler(deps, examplePrompts);

  const server = http.createServer(options.app);

  server.on('upgrade', (request, socket, head) => {
    handleUpgrade(request, socket, head);
  });

  wss.on('connection', ws => {
    handleConnection(ws as ExtWebSocket);
  });

  const heartbeatMs = options.heartbeatIntervalMs ?? 30_000;

  const heartbeatInterval = setInterval(() => {
    wss.clients.forEach(ws => {
      const extWs = ws as ExtWebSocket;
      if (!extWs.isAlive) {
        extWs.terminate();
        return;
      }
      extWs.isAlive = false;
      extWs.ping();
    });
  }, heartbeatMs);

  // The listening socket should hold the process open, not the heartbeat: an engine never started must not.
  heartbeatInterval.unref();

  wss.on('close', () => clearInterval(heartbeatInterval));

  return {
    server,
    wss,
    start: (port?: number) =>
      new Promise<void>((resolve, reject) => {
        // Refused before the handlers are touched: `listen` throws on a running server, and the swap below stripped its handler.
        if (server.listening) {
          reject(new Error('HAL Engine is already started'));
          return;
        }

        // ?? not ||, so a configured port 0 means "let the OS choose" rather than 8086.
        const p = port ?? options.port ?? (Number(process.env.PORT) || 8086);

        // Without this an EADDRINUSE settles nothing and takes the process down as an unhandled event.
        const onError = (error: Error) => reject(error);
        server.once('error', onError);

        // A listener left from a previous start would report this bind failure as a running server breaking.
        server.removeListener('error', logLateError);

        server.listen(p, () => {
          server.removeListener('error', onError);

          // Past the listen window nothing is listening, and an 'error' with no handler ends the process.
          server.on('error', logLateError);

          // The bound port, not the requested one: a configured 0 means the OS chose it.
          log.info('server', 'HAL Engine started', {port: boundPort(server, p)});
          resolve();
        });
      }),
    stop: () =>
      new Promise<void>((resolve, reject) => {
        wss.clients.forEach(ws => ws.close(1001, 'Server shutting down'));
        wss.close();
        clearInterval(heartbeatInterval);

        // Nothing to close after a refused start or a second stop: `close` would reject for a server that never ran.
        if (!server.listening) {
          resolve();
          return;
        }
        server.close(err => (err ? reject(err) : resolve()));
      }),
  };
}

// A running server's error is a condition to report, not a reason to exit; the consumer decides what to do.
function logLateError(error: Error): void {
  log.error('server', 'server error after start', {error: error.message});
}

function boundPort(server: http.Server, requested: number): number {
  const address = server.address();
  return typeof address === 'object' && address !== null ? address.port : requested;
}

import type {WsAuthenticator, HttpAuthMiddleware} from './types/auth.js';
import type {SessionStore} from './types/sessionStore.js';
import type {PromptBuilderConfig} from './infrastructure/builders/promptBuilder.js';
import type {ContextConfig} from './orchestration/conversationContext.js';
import type {ProviderConfig} from './providers/providerFactory.js';
import {withRetry} from './providers/withRetry.js';
import type {RetryPolicy} from './providers/withRetry.js';
import type {Logger} from './shared/logger.js';
import {setLogger} from './shared/logger.js';
import type {ChatSession} from './types/session.js';
import type {HalServer} from './transport/createServer.js';
import type {ConnectInfo} from './transport/ws/sessionResume.js';
import {PromptBuilder} from './infrastructure/builders/promptBuilder.js';
import {createChatOrchestrator} from './orchestration/chatOrchestrator.js';
import type {OrchestratorHooks} from './orchestration/chatOrchestrator.js';
import {createProvider} from './providers/providerFactory.js';
import {ToolRegistry} from './orchestration/tools/registry.js';
import {InMemorySessionStore} from './infrastructure/stores/inMemorySessionStore.js';
import {createApp} from './transport/createApp.js';
import type {HalAppOptions} from './transport/createApp.js';
import {createServer} from './transport/createServer.js';
import type {SessionResumeOptions} from './transport/ws/sessionResume.js';

export interface HalEngineConfig {
  provider: ProviderConfig;
  resilience?: RetryPolicy;
  prompt: PromptBuilderConfig;
  tools?: ToolRegistry;
  session?: SessionStore;
  transport?: {
    port?: number;
    corsOrigin?: string | string[];
    basePath?: string;
    heartbeatIntervalMs?: number;
    additionalRoutes?: HalAppOptions['additionalRoutes'];
    rootRoutes?: HalAppOptions['rootRoutes'];
    errorHandler?: HalAppOptions['errorHandler'];
    resume?: SessionResumeOptions;
  };
  auth: {
    ws: WsAuthenticator;
    http?: HttpAuthMiddleware;
  };
  orchestrator?: {
    maxToolRounds?: number;
    /** How long one tool call may take before it is abandoned and answered with a timeout result; default 30000, and 0 waits forever. */
    toolTimeoutMs?: number;
    contextConfig?: Partial<ContextConfig>;
    /** Lifecycle hooks: called before and after each phase of processing a user message. */
    hooks?: OrchestratorHooks;
  };
  // Replaces the package's logger process-wide, not per engine: there is one `log` per process.
  logger?: Logger;
  onConnect?: (session: ChatSession, connection: ConnectInfo) => void | Promise<void>;
  onDisconnect?: (sessionId: string) => void | Promise<void>;
}

export interface HalEngine extends HalServer {
  app: ReturnType<typeof createApp>;
  orchestrator: ReturnType<typeof createChatOrchestrator>;
  toolRegistry: ToolRegistry;
}

export function createHalEngine(config: HalEngineConfig): HalEngine {
  // Before anything else builds, so a supplied logger receives this engine's first line.
  if (config.logger) setLogger(config.logger);

  const toolRegistry = config.tools ?? new ToolRegistry();
  const sessionStore = config.session ?? new InMemorySessionStore();
  const basePath = config.transport?.basePath ?? '/hal';

  const baseProvider = createProvider(config.provider);
  const provider = config.resilience ? withRetry(baseProvider, config.resilience) : baseProvider;
  const promptBuilder = new PromptBuilder(config.prompt);
  const orchestrator = createChatOrchestrator(provider, promptBuilder, toolRegistry, {
    maxToolRounds: config.orchestrator?.maxToolRounds,
    toolTimeoutMs: config.orchestrator?.toolTimeoutMs,
    contextConfig: config.orchestrator?.contextConfig,
    hooks: config.orchestrator?.hooks,
    sessionStore,
  });

  const app = createApp({
    corsOrigin: config.transport?.corsOrigin,
    basePath,
    authMiddleware: config.auth.http,
    orchestrator,
    sessionStore,
    additionalRoutes: config.transport?.additionalRoutes,
    rootRoutes: config.transport?.rootRoutes,
    errorHandler: config.transport?.errorHandler,
  });

  const halServer = createServer({
    app,
    wsAuth: config.auth.ws,
    sessionStore,
    orchestrator,
    toolRegistry,
    basePath,
    port: config.transport?.port,
    heartbeatIntervalMs: config.transport?.heartbeatIntervalMs,
    onConnect: config.onConnect,
    onDisconnect: config.onDisconnect,
    resume: config.transport?.resume,
  });

  return {
    ...halServer,
    app,
    orchestrator,
    toolRegistry,
  };
}

import type {ChatSession} from './session.js';

/** A value a store may return directly or resolve to, so a database-backed member needs no new interface. */
export type Awaitable<T> = T | Promise<T>;

export interface BaseSession {
  sessionId: string;
  userId: string | number;
}

/** What a store knows of a session id. `expired` carries the owner's id, so ownership can be checked, and never the conversation. */
export type SessionLookup<T extends BaseSession = ChatSession> =
  {status: 'active'; session: T} | {status: 'expired'; userId: string | number} | {status: 'missing'};

/** What a conversation list needs of one session: never its entries, and never its credentials. */
export interface SessionSummary {
  sessionId: string;
  createdAt: Date;
  updatedAt: Date;
  entryCount: number;
}

/** Where a page of conversations resumes from: the last row the caller saw, which a `SessionSummary` satisfies. */
export interface SessionCursor {
  /** A `Date`, an ISO string or an epoch number, so a row that went through JSON still pages (specs/hal-engine-conversation-list/spec.md). */
  updatedAt: Date | string | number;
  sessionId: string;
}

/** A window onto a user's conversations, newest activity first; `before` pages down that same order. */
export interface SessionListOptions {
  limit?: number;
  before?: SessionCursor;
}

export interface SessionCreateOptions {
  authHeaders?: ChatSession['authHeaders'];
  workspaceId?: string | number;
}

export interface SessionStore<T extends BaseSession = ChatSession> {
  create(sessionId: string, userId: string | number, options?: SessionCreateOptions): Awaitable<T>;
  get(sessionId: string): Awaitable<T | undefined>;
  delete(sessionId: string): Awaitable<boolean>;
  count(): Awaitable<number>;
  clear(): Awaitable<void>;
  /** Drops a session the client never received, without erasing anything a consumer would want kept. */
  evict?(sessionId: string): Awaitable<boolean>;
  /** Write signal: fires once per processed user message; failures are swallowed (specs/hal-engine-session-write-signal/spec.md). */
  save?(session: T): Awaitable<void>;
  /** Summaries of the user's conversations, newest activity first, so a client can offer a list of them (specs/hal-engine-conversation-list/spec.md). */
  listFor?(userId: string | number, options?: SessionListOptions): Awaitable<SessionSummary[]>;
  /** The user's most recently active session the store still holds, so a connect that names none can continue it (specs/hal-engine-session-resume/spec.md). */
  latestFor?(userId: string | number): Awaitable<T | undefined>;
  /** Tells an expired session from a missing one; `missing` is always a permitted answer, and a store without it behaves as `get` (specs/hal-engine-session-resume/spec.md). */
  lookup?(sessionId: string): Awaitable<SessionLookup<T>>;
}

import type {SessionEntry} from './session.js';

export interface UserMessagePayload {
  type: 'user_message';
  content: string;
}

export interface PingMessage {
  type: 'ping';
  timestamp: number;
}

export interface ListSessionsMessage {
  type: 'list_sessions';
  limit?: number;
  before?: {
    updatedAt: string | number;
    sessionId: string;
  };
}

export type IncomingMessage = UserMessagePayload | PingMessage | ListSessionsMessage;

export interface ConnectedMessage {
  type: 'connected';
  sessionId: string;
  message: string;
  examplePrompts: string[];
  resumed?: boolean;
  entryCount?: number;
  /** Why a named id was not rejoined: `expired` only for the session's own owner, `unknown` for every other case. */
  resumeFailure?: 'expired' | 'unknown';
}

export interface EntryUpsertMessage {
  type: 'entry_upsert';
  index: number;
  entry: SessionEntry;
}

export interface EntryDeltaMessage {
  type: 'entry_delta';
  index: number;
  delta: string;
}

export interface EntryCommitMessage {
  type: 'entry_commit';
  index: number;
}

export interface ErrorMessage {
  type: 'error';
  code: string;
  message: string;
}

export interface PongMessage {
  type: 'pong';
  timestamp: number;
}

export interface EntrySkipMessage {
  type: 'entry_skip';
  index: number;
}

export interface StreamEndMessage {
  type: 'stream_end';
}

export interface SessionSummaryFrame {
  sessionId: string;
  createdAt: string;
  updatedAt: string;
  entryCount: number;
}

export interface SessionListMessage {
  type: 'session_list';
  sessions: SessionSummaryFrame[];
}

export type OutgoingMessage =
  | ConnectedMessage
  | EntryUpsertMessage
  | EntryDeltaMessage
  | EntryCommitMessage
  | EntrySkipMessage
  | ErrorMessage
  | PongMessage
  | StreamEndMessage
  | SessionListMessage;

export {ErrorCodes} from './session.js';

import type {AddressInfo} from 'node:net';
import {WebSocket} from 'ws';
import type {Express} from 'express';
import {createServer} from './createServer.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {answeringOrchestrator, delegatingTo, teardown} from './wsTestSupport.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import type {SessionCursor, SessionListOptions, SessionStore, SessionSummary} from '../types/sessionStore.js';
import {setLogger} from '../shared/logger.js';

// Real upgrades over a real socket: what the list_sessions frame answers is the contract, and no double can observe it.

interface Frame {
  type: string;
  sessionId?: string;
  sessions?: Array<{sessionId: string; createdAt: string; updatedAt: string; entryCount: number}>;
  code?: string;
  message?: string;
}

const servers: Array<ReturnType<typeof createServer>> = [];
const clients: WebSocket[] = [];
const logLines: Array<{level: string; category: string; message: string; fields?: Record<string, unknown>}> = [];

beforeEach(() => {
  logLines.length = 0;
  const record = (level: string) => (category: string, message: string, fields?: Record<string, unknown>) =>
    void logLines.push({level, category, message, fields});
  setLogger({debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')});
});

afterEach(async () => {
  await teardown(clients, servers);
  setLogger();
});

const startEngine = async (store: SessionStore, userId: string | number = 'u1') => {
  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: userId}),
    sessionStore: store,
    orchestrator: answeringOrchestrator,
  });
  await hal.start(0);
  servers.push(hal);
  const {port} = hal.server.address() as AddressInfo;
  return `ws://127.0.0.1:${port}/hal/ws`;
};

const askAfterConnect = async (url: string, outbound: unknown): Promise<{connected: Frame; frames: Frame[]}> => {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, 't']);
  clients.push(client);
  const frames: Frame[] = [];
  let connected: Frame = {type: ''};
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame;
      if (frame.type === 'pong') {
        resolve();
        return;
      }
      if (frame.type !== 'connected') {
        frames.push(frame);
        return;
      }
      connected = frame;
      client.send(typeof outbound === 'string' ? outbound : JSON.stringify(outbound));
      client.send(JSON.stringify({type: 'ping', timestamp: 1}));
    });
  });
  return {connected, frames};
};

describe('listing conversations over the WebSocket protocol', () => {
  it('answers list_sessions for the authenticated user with ISO dates, forwarding limit and before while ignoring any client userId', async () => {
    const inner = new InMemorySessionStore();
    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
    const summaries: SessionSummary[] = [
      {
        sessionId: 's2',
        createdAt: new Date('2026-01-01T00:00:00.000Z'),
        updatedAt: new Date('2026-01-01T00:02:00.000Z'),
        entryCount: 4,
      },
    ];
    const store: SessionStore = {
      ...delegatingTo(inner),
      listFor: (userId, options) => {
        seen.push({userId, options});
        return summaries;
      },
    };
    const url = await startEngine(store, 'u1');
    const before: SessionCursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};

    const {frames} = await askAfterConnect(url, {type: 'list_sessions', limit: 10, before, userId: 'u2'});

    expect({seen, frames}).toEqual({
      seen: [{userId: 'u1', options: {limit: 10, before}}],
      frames: [
        {
          type: 'session_list',
          sessions: [
            {
              sessionId: 's2',
              createdAt: '2026-01-01T00:00:00.000Z',
              updatedAt: '2026-01-01T00:02:00.000Z',
              entryCount: 4,
            },
          ],
        },
      ],
    });
  });

  it('answers an empty session_list when the store has no listFor, and SERVER_ERROR with a ws error log when listFor throws', async () => {
    const inner = new InMemorySessionStore();
    const withoutList = await startEngine(delegatingTo(inner));
    const failingList = await startEngine({
      ...delegatingTo(inner),
      listFor: () => Promise.reject(new Error('database offline')),
    });

    const unimplemented = await askAfterConnect(withoutList, {type: 'list_sessions'});
    const failed = await askAfterConnect(failingList, {type: 'list_sessions'});

    expect({
      unimplemented: unimplemented.frames,
      failed: failed.frames.map(frame => ({type: frame.type, code: frame.code})),
      logged: logLines.filter(line => line.level === 'error' && line.category === 'ws'),
    }).toEqual({
      unimplemented: [{type: 'session_list', sessions: []}],
      failed: [{type: 'error', code: 'SERVER_ERROR'}],
      logged: [
        {
          level: 'error',
          category: 'ws',
          message: expect.any(String),
          fields: expect.objectContaining({userId: 'u1', error: 'database offline'}),
        },
      ],
    });
  });

  it('accepts a bare list_sessions frame and rejects a malformed limit or before with INVALID_MESSAGE without calling listFor', async () => {
    const inner = new InMemorySessionStore();
    let calls = 0;
    const store: SessionStore = {
      ...delegatingTo(inner),
      listFor: () => {
        calls += 1;
        return [];
      },
    };
    const url = await startEngine(store);
    const badFrames = [
      {type: 'list_sessions', limit: 'ten'},
      {type: 'list_sessions', limit: -1},
      {type: 'list_sessions', limit: 1.5},
      {type: 'list_sessions', before: 'not-an-object'},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
      {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
      {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}},
    ];

    const codes: Array<string | undefined> = [];
    for (const bad of badFrames) {
      const {frames} = await askAfterConnect(url, bad);
      codes.push(frames[0]?.code);
    }
    const {frames: accepted} = await askAfterConnect(url, {type: 'list_sessions'});

    expect({codes, accepted, calls}).toEqual({
      codes: Array(badFrames.length).fill('INVALID_MESSAGE'),
      accepted: [{type: 'session_list', sessions: []}],
      calls: 1,
    });
  });
});

import {jest} from '@jest/globals';
import {WebSocket} from 'ws';
import {createMessageHandler} from './messageHandler.js';
import {createChatOrchestrator, TOOL_BUDGET_EXHAUSTED} from '../../orchestration/chatOrchestrator.js';
import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import {ToolRegistry} from '../../orchestration/tools/registry.js';
import {PromptBuilder} from '../../infrastructure/builders/promptBuilder.js';
import type {AIProvider, MessageChunk, ToolCall} from '../../types/ai.js';
import {AIError} from '../../types/ai.js';
import type {ChatSession, SessionEntry} from '../../types/session.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {PerSessionLock} from '../../shared/perSessionLock.js';
import {deferred} from '../wsTestSupport.js';

// The frames, in order, are the contract - above all for suppression, which retracts.

// One line per frame; entries carry generated timestamps no assertion should read.
const wire = (sent: OutgoingMessage[]): string[] =>
  sent.map(frame => {
    if (frame.type === 'entry_upsert') {
      const content = 'content' in frame.entry ? frame.entry.content : '';
      return `upsert ${frame.index} ${frame.entry.role} ${JSON.stringify(content)}`;
    }
    if (frame.type === 'entry_delta') return `delta ${frame.index} ${JSON.stringify(frame.delta)}`;
    if (frame.type === 'entry_commit') return `commit ${frame.index}`;
    if (frame.type === 'entry_skip') return `skip ${frame.index}`;
    if (frame.type === 'error') return `error ${frame.code}`;
    if (frame.type === 'pong') return `pong ${frame.timestamp}`;
    return frame.type;
  });

const text = (value: string): MessageChunk => ({type: 'text', text: value});
const STOP: MessageChunk = {type: 'stop', stopReason: 'end_turn'};
const SUPPRESS = {type: 'suppress_output'} as unknown as MessageChunk;

interface StreamScript {
  failWith?: Error;
  pauseAfter?: {chunks: number; until: Promise<void>};
}

const harness = (chunks: MessageChunk[], {failWith, pauseAfter}: StreamScript = {}) => {
  const sent: OutgoingMessage[] = [];
  const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;

  const stream = async function* (): AsyncGenerator<MessageChunk> {
    for (const [position, chunk] of chunks.entries()) {
      if (pauseAfter && position === pauseAfter.chunks) await pauseAfter.until;
      yield chunk;
    }
    if (failWith) throw failWith;
  };

  const processMessageStream = jest.fn(stream);
  const orchestrator = {processMessageStream} as unknown as ChatOrchestrator;
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};

  const handle = createMessageHandler(orchestrator);

  return {
    session,
    processMessageStream,
    sent,
    frames: () => wire(sent),
    send: (raw: unknown = {type: 'user_message', content: 'hello'}, signal?: AbortSignal) =>
      handle(ws, session, raw, signal),
  };
};

describe('the websocket message handler', () => {
  describe('dispatch', () => {
    it('rejects an unparseable message and never starts a stream', async () => {
      const h = harness([]);

      await h.send({type: 'nonsense'});

      const {calls} = h.processMessageStream.mock;

      expect({frames: h.frames(), streams: calls.length}).toEqual({frames: ['error INVALID_MESSAGE'], streams: 0});
    });

    it('answers a ping with the timestamp it was given', async () => {
      const h = harness([]);

      await h.send({type: 'ping', timestamp: 1234});

      expect(h.frames()).toEqual(['pong 1234']);
    });
  });

  describe('a plain assistant reply', () => {
    it('sends the user entry, then the assistant entry, its delta, its commit and stream_end', async () => {
      const h = harness([text('hi there'), STOP]);

      await h.send();

      expect(h.frames()).toEqual([
        'upsert 0 user "hello"',
        'upsert 1 assistant ""',
        'delta 1 "hi there"',
        'commit 1',
        'stream_end',
      ]);
    });

    it('leaves the committed assistant entry in the session, no longer streaming', async () => {
      const h = harness([text('hi there'), STOP]);

      await h.send();

      const {entries} = h.session;

      expect(entries[1]).toMatchObject({role: 'assistant', content: 'hi there', isStreaming: false});
    });
  });

  describe('thinking segments', () => {
    it('commits the thinking entry before the assistant entry opens', async () => {
      const h = harness([text('<thinking>pondering</thinking>answer'), STOP]);

      await h.send();

      expect(h.frames()).toEqual([
        'upsert 0 user "hello"',
        'upsert 1 thinking ""',
        'delta 1 "pondering"',
        'commit 1',
        'upsert 2 assistant ""',
        'delta 2 "answer"',
        'commit 2',
        'stream_end',
      ]);
    });

    it('commits the thinking entry when text resumes, not when a tool entry appears', async () => {
      const h = harness([
        text('<thinking>I should look up the weather for Berlin.</thinking>'),
        {type: 'tool_use', toolCall: {id: 'c1', name: 'get_weather', input: {location: 'Berlin'}}} as MessageChunk,
        text('Berlin currently has '),
        text('a temperature of 18 degrees Celsius with clear skies.'),
        STOP,
      ]);

      await h.send();

      expect(h.frames()).toEqual([
        'upsert 0 user "hello"',
        'upsert 1 thinking ""',
        'delta 1 "I should look up the weather for Berlin."',
        'upsert 2 tool ""',
        'commit 1',
        'upsert 3 assistant ""',
        'delta 3 "Berlin currently has "',
        'delta 3 "a temperature of 18 degrees Celsius with clear skies."',
        'commit 3',
        'stream_end',
      ]);
    });
  });

  describe('tool chunks', () => {
    it('sends a tool entry for a tool call', async () => {
      const h = harness([{type: 'tool_use', toolCall: {id: 'c1', name: 'lookup', input: {q: 1}}}, STOP]);

      await h.send();

      expect(h.frames()).toEqual(['upsert 0 user "hello"', 'upsert 1 tool ""', 'stream_end']);
    });

    it('forwards a tool result to the client untouched', async () => {
      const forwarded = {type: 'entry_commit', index: 41} as OutgoingMessage;
      const h = harness([{type: 'tool_result', clientMessages: [forwarded]} as MessageChunk, STOP]);

      await h.send();

      expect(h.frames()).toEqual(['upsert 0 user "hello"', 'commit 41', 'stream_end']);
    });
  });

  describe('suppression', () => {
    it('blanks an assistant entry that was already sent', async () => {
      const h = harness([text('leaked'), STOP, SUPPRESS]);

      await h.send();

      expect(h.frames()).toEqual([
        'upsert 0 user "hello"',
        'upsert 1 assistant ""',
        'delta 1 "leaked"',
        'commit 1',
        'upsert 1 assistant ""',
        'stream_end',
      ]);
    });

    it('never blanks a thinking entry, only assistant ones', async () => {
      const h = harness([text('<thinking>private</thinking>said'), STOP, SUPPRESS]);

      await h.send();

      expect(h.frames().filter(frame => frame.startsWith('upsert 1'))).toEqual(['upsert 1 thinking ""']);
    });

    it('skips rather than upserts a segment opened after suppression', async () => {
      const h = harness([SUPPRESS, text('hidden'), STOP]);

      await h.send();

      expect(h.frames()).toEqual(['upsert 0 user "hello"', 'skip 1', 'stream_end']);
    });

    it('still records a suppressed reply in the session, so history keeps it', async () => {
      const h = harness([SUPPRESS, text('hidden'), STOP]);

      await h.send();

      const {entries} = h.session;

      expect(entries[1]).toMatchObject({role: 'assistant', content: 'hidden', isStreaming: false});
    });

    it('does not resurrect an entry the client only ever saw skipped', async () => {
      const h = harness([SUPPRESS, text('hidden'), STOP, SUPPRESS]);

      await h.send();

      expect(h.frames()).toEqual(['upsert 0 user "hello"', 'skip 1', 'stream_end']);
    });

    it('blanks each sent entry once, so a second suppression repeats nothing', async () => {
      const h = harness([text('leaked'), STOP, SUPPRESS, SUPPRESS]);

      await h.send();

      expect(h.frames().filter(frame => frame === 'upsert 1 assistant ""')).toHaveLength(2);
    });

    it('marks a sent assistant entry it blanked as suppressed in the session, keeping its text', async () => {
      const h = harness([text('leaked'), STOP, SUPPRESS]);

      await h.send();

      const [, answer] = h.session.entries;
      expect(answer).toMatchObject({role: 'assistant', content: 'leaked', suppressed: true});
    });

    it('marks a segment opened after suppression as suppressed in the session', async () => {
      const h = harness([SUPPRESS, text('hidden'), STOP]);

      await h.send();

      const [, answer] = h.session.entries;
      expect(answer).toMatchObject({role: 'assistant', content: 'hidden', suppressed: true});
    });

    it('leaves a thinking entry the client kept seeing unmarked, and marks the blanked answer', async () => {
      const h = harness([text('<thinking>private</thinking>said'), STOP, SUPPRESS]);

      await h.send();

      const [, thinking, answer] = h.session.entries;
      expect({thinking: 'suppressed' in thinking, answer}).toMatchObject({
        thinking: false,
        answer: {role: 'assistant', content: 'said', suppressed: true},
      });
    });

    it('commits and retracts an answer still open when suppression begins, and skips what follows as a new entry', async () => {
      const h = harness([text('before'), SUPPRESS, text(' after'), STOP]);

      await h.send();

      const [, answer, after] = h.session.entries;
      expect({frames: h.frames(), answer, after}).toMatchObject({
        frames: [
          'upsert 0 user "hello"',
          'upsert 1 assistant ""',
          'delta 1 "before"',
          'commit 1',
          'upsert 1 assistant ""',
          'skip 2',
          'stream_end',
        ],
        answer: {role: 'assistant', content: 'before', isStreaming: false, suppressed: true},
        after: {role: 'assistant', content: ' after', suppressed: true},
      });
    });

    it('commits a thought still open when suppression begins as the client saw it, and skips what follows', async () => {
      const h = harness([text('<thinking>early'), SUPPRESS, text(' later</thinking>'), STOP]);

      await h.send();

      const [, thought, after] = h.session.entries;
      expect({frames: h.frames(), thought, marked: 'suppressed' in thought, after}).toMatchObject({
        frames: [
          'upsert 0 user "hello"',
          'upsert 1 thinking ""',
          'delta 1 "early"',
          'commit 1',
          'skip 2',
          'stream_end',
        ],
        thought: {role: 'thinking', content: 'early', isStreaming: false},
        marked: false,
        after: {role: 'thinking', content: ' later', suppressed: true},
      });
    });
  });

  describe('failures', () => {
    it('tells the client to retry when the provider is rate limited', async () => {
      // eslint-disable-next-line re-lint/no-flag-params -- AIError's retryable flag; see adrs/ADR-006-lint-suppressions.md
      const h = harness([], {failWith: new AIError('slow down', 'RATE_LIMITED', true)});

