    });

    it('answers a blank user_message with INVALID_MESSAGE then stream_end', async () => {
      expect(await invalidRun('   ')).toEqual(REFUSED);
    });

    it('answers an over-length user_message with INVALID_MESSAGE then stream_end', async () => {
